final class VeEngine extends ffi.Opaque {}

/// Decoded PCM handed back from ve_decode_file (interleaved stereo f32, `frames * 2`
/// floats). Free with ve_free_pcm.
final class VePcm extends ffi.Struct {
  external ffi.Pointer<ffi.Float> ptr;

  @ffi.Size()
  external int frames;

  @ffi.Uint32()
  external int rate;
}

/// Audio device descriptor (ve_enum_output_devices). Fixed-size NUL-terminated strings keep
/// it POD across the ABI.
final class VeDeviceInfo extends ffi.Struct {
  /// stable CoreAudio device UID — the persist key
  @ffi.Array.multi([128])
  external ffi.Array<ffi.Char> uid;

  /// human-readable name
  @ffi.Array.multi([128])
  external ffi.Array<ffi.Char> name;

  /// native sample rate (0 if unknown)
  @ffi.Uint32()
  external int rate;

  /// 1 if the system default
  @ffi.Uint8()
  external int is_default;

  /// 1 = input device, 0 = output
  @ffi.Uint8()
  external int is_input;

  /// 1 if on a Bluetooth transport (same-device in+out degrades output)
  @ffi.Uint8()
  external int is_bluetooth;
}

const int VE_DECODE_OK = 0;

const int VE_DECODE_ERR = -1;

const int VE_DECODE_TOO_LONG = -2;
